import AppKit

/// The EQ section (spec §11 AU-31, AU-32, AU-36, AU-38): the clip's EQ, after
/// the channel pick and before the hum notch and noise reduction, so the
/// Sound sub-tab's sections read in the signal's order. `set_audio`'s `eq`
/// is its MCP mirror.
///
/// The drawn response (`AudioEQCurveView`), Bypass, the three presets, then
/// per slot a checkbox writing that slot's default and its Frequency, Gain,
/// Q and Slope. Every control writes a whole `EqProps`, the compressor's way
/// (`EqProps.dictionary` writes every slot, so a patch that merges per key
/// still turns one off). With an action selected it writes the action's end,
/// where a slot turned off is keyed off as `audio.eq.<slot>` (spec §11 AU-88).
extension AudioPane {

    func eqSection() -> InspectorSection {
        let binding = self.binding
        func current() -> EqProps { binding.audioProps.eq ?? EqProps() }
        func on() -> Bool { binding.audioProps.eq != nil }
        func ops(_ next: EqProps) -> [ReelOp] { binding.ops(audio: AudioPatch(eq: .some(next))) }
        let curve = AudioEQCurveView(read: {
            guard !binding.mixedAudio({ $0.eq }), !binding.mixedAudio({ $0.hum }) else {
                return nil
            }
            return (binding.audioProps.eq, binding.audioProps.hum)
        })
        let presets = EqPreset.allCases.map { preset in
            inspectorButton(
                preset.title, binding, name: "EQ \(preset.title)",
                ops: { ops(preset.applied(to: current())) })
        }
        var rows: [NSView] = [
            inspectorRow(nil, [curve], mixed: { binding.mixedAudio { $0.eq } }),
            inspectorCheckRow(
                "Bypass", binding, name: "EQ Bypass",
                read: { current().bypass },
                ops: { value in
                    var next = current()
                    next.bypass = value
                    return ops(next)
                },
                mixed: { binding.mixedAudio { $0.eq?.bypass } }, enabled: on),
            inspectorButtonRow(presets),
        ]
        rows += passRows(
            "High-pass", \.highPass, fallback: .highPass, quick: [40, 60, 80, 100, 120],
            current: current, ops: ops)
        rows += shelfRows(
            "Low shelf", \.lowShelf, fallback: .lowShelf, quick: [80, 100, 150, 200],
            current: current, ops: ops)
        rows += bandRows("Band 1", \.band1, at: 300, current: current, ops: ops)
        rows += bandRows("Band 2", \.band2, at: 1000, current: current, ops: ops)
        rows += bandRows("Band 3", \.band3, at: 4000, current: current, ops: ops)
        rows += shelfRows(
            "High shelf", \.highShelf, fallback: .highShelf, quick: [6000, 8000, 10_000, 12_000],
            current: current, ops: ops)
        rows += passRows(
            "Low-pass", \.lowPass, fallback: .lowPass, quick: [8000, 10_000, 12_000, 16_000],
            current: current, ops: ops)
        return InspectorSection(
            id: "audio.eq", title: "EQ",
            summary: {
                guard let eq = binding.audioProps.eq else { return "off" }
                return eq.bypass ? "bypassed" : "\(eq.activeCount) on"
            },
            reset: { binding.apply("EQ", audio: AudioPatch(eq: .some(nil))) },
            defaultExpanded: false,
            rows: rows)
    }

    /// A slot's checkbox: on writes `fallback` into the slot (the EQ made if
    /// there was none), off clears the slot.
    private func slotCheck<Slot: Equatable>(
        _ title: String, _ path: WritableKeyPath<EqProps, Slot?>, fallback: Slot,
        current: @escaping () -> EqProps, ops: @escaping (EqProps) -> [ReelOp]
    ) -> NSView {
        let binding = self.binding
        return inspectorCheckRow(
            title, binding, name: "EQ \(title)",
            read: { current()[keyPath: path] != nil },
            ops: { value in
                var next = current()
                next[keyPath: path] = value ? fallback : nil
                return ops(next)
            },
            mixed: { binding.mixedAudio { $0.eq?[keyPath: path] != nil } })
    }

    private func frequencyRow<Slot>(
        _ title: String, _ path: WritableKeyPath<EqProps, Slot?>,
        _ frequency: WritableKeyPath<Slot, Double>, quick: [Double], off: Double,
        current: @escaping () -> EqProps, ops: @escaping (EqProps) -> [ReelOp]
    ) -> NSView where Slot: Equatable {
        let binding = self.binding
        return inspectorValueRow(
            "Frequency", binding, name: "EQ \(title) Frequency", unit: " Hz", decimals: 0,
            min: 20, max: 20_000, quick: quick, slider: false,
            width: InspectorMetrics.wideFieldWidth,
            read: { current()[keyPath: path]?[keyPath: frequency] ?? off },
            ops: { value in
                var next = current()
                next[keyPath: path]?[keyPath: frequency] = value
                return ops(next)
            },
            mixed: { binding.mixedAudio { $0.eq?[keyPath: path]?[keyPath: frequency] } },
            enabled: { current()[keyPath: path] != nil })
    }

    private func gainRow<Slot>(
        _ title: String, _ path: WritableKeyPath<EqProps, Slot?>,
        _ gain: WritableKeyPath<Slot, Double>,
        current: @escaping () -> EqProps, ops: @escaping (EqProps) -> [ReelOp]
    ) -> NSView where Slot: Equatable {
        let binding = self.binding
        return inspectorValueRow(
            "Gain", binding, name: "EQ \(title) Gain", unit: " dB", decimals: 1,
            min: -24, max: 24, quick: [-6, -3, 0, 3, 6],
            read: { current()[keyPath: path]?[keyPath: gain] ?? 0 },
            ops: { value in
                var next = current()
                next[keyPath: path]?[keyPath: gain] = value
                return ops(next)
            },
            mixed: { binding.mixedAudio { $0.eq?[keyPath: path]?[keyPath: gain] } },
            enabled: { current()[keyPath: path] != nil })
    }

    private func passRows(
        _ title: String, _ path: WritableKeyPath<EqProps, EqPassProps?>, fallback: EqPassProps,
        quick: [Double], current: @escaping () -> EqProps, ops: @escaping (EqProps) -> [ReelOp]
    ) -> [NSView] {
        let binding = self.binding
        return [
            slotCheck(title, path, fallback: fallback, current: current, ops: ops),
            frequencyRow(
                title, path, \.frequency, quick: quick, off: fallback.frequency,
                current: current, ops: ops),
            inspectorPopupRow(
                "Slope", binding, name: "EQ \(title) Slope", items: ["12 dB/oct", "24 dB/oct"],
                read: { (current()[keyPath: path]?.slope ?? 12) >= 18 ? 1 : 0 },
                ops: { index in
                    var next = current()
                    next[keyPath: path]?.slope = index == 1 ? 24 : 12
                    return ops(next)
                },
                mixed: { binding.mixedAudio { $0.eq?[keyPath: path]?.slope } },
                enabled: { current()[keyPath: path] != nil }),
        ]
    }

    private func shelfRows(
        _ title: String, _ path: WritableKeyPath<EqProps, EqShelfProps?>,
        fallback: EqShelfProps, quick: [Double], current: @escaping () -> EqProps,
        ops: @escaping (EqProps) -> [ReelOp]
    ) -> [NSView] {
        [
            slotCheck(title, path, fallback: fallback, current: current, ops: ops),
            frequencyRow(
                title, path, \.frequency, quick: quick, off: fallback.frequency,
                current: current, ops: ops),
            gainRow(title, path, \.gainDb, current: current, ops: ops),
        ]
    }

    /// A bell's rows; its checkbox writes `{at, 0 dB, Q 1}` (AU-38: bands 1,
    /// 2 and 3 at 300, 1000 and 4000 Hz).
    private func bandRows(
        _ title: String, _ path: WritableKeyPath<EqProps, EqBandProps?>, at frequency: Double,
        current: @escaping () -> EqProps, ops: @escaping (EqProps) -> [ReelOp]
    ) -> [NSView] {
        let binding = self.binding
        return [
            slotCheck(
                title, path, fallback: EqBandProps(frequency: frequency), current: current,
                ops: ops),
            frequencyRow(
                title, path, \.frequency, quick: [100, 300, 1000, 2500, 4000, 8000],
                off: frequency, current: current, ops: ops),
            gainRow(title, path, \.gainDb, current: current, ops: ops),
            inspectorValueRow(
                "Q", binding, name: "EQ \(title) Q", decimals: 2, min: 0.1, max: 10,
                quick: [0.5, 0.7, 1, 2, 4],
                read: { current()[keyPath: path]?.q ?? 1 },
                ops: { value in
                    var next = current()
                    next[keyPath: path]?.q = value
                    return ops(next)
                },
                mixed: { binding.mixedAudio { $0.eq?[keyPath: path]?.q } },
                enabled: { current()[keyPath: path] != nil }),
        ]
    }
}
import Foundation

// The read-only mirror of a clip's EQ, hum notch and channel pick (format 32, spec §11 AU-31,
// AU-33, AU-34): `EqProps` and its slots, `HumProps`, `AudioChannelChoice`, and the inspector's
// three presets (`EqPreset`, AU-32). The core's `model_audio.rs` is the vocabulary; snake keys
// arrive through `.convertFromSnakeCase` (`band_1` is `band1`). The DSP is
// `AudioBiquad.swift`'s and `AudioEQStage.swift`'s.

/// Which channels of a stereo source play (AU-34). A one-channel track
/// ignores it, as it ignores pan.
enum AudioChannelChoice: String, Codable, CaseIterable {
    case both, left, right, swapped

    /// The Channels popup's words.
    var title: String {
        switch self {
        case .both: return "Both"
        case .left: return "Left Only"
        case .right: return "Right Only"
        case .swapped: return "Swap Left and Right"
        }
    }
}

/// A Butterworth pass: its corner in Hz and its slope, 12 or 24 dB/octave.
struct EqPassProps: Codable, Equatable {
    var frequency: Double
    var slope: Int

    init(frequency: Double, slope: Int = 12) {
        self.frequency = frequency
        self.slope = slope
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        frequency = c.lenient(.frequency, 1000)
        slope = c.lenient(.slope, 12)
    }

    static let highPass = EqPassProps(frequency: 80)
    static let lowPass = EqPassProps(frequency: 12_000)

    var dictionary: [String: Any] { ["frequency": frequency, "slope": slope] }
}

/// An RBJ shelf (S = 1): its corner in Hz and its gain in dB.
struct EqShelfProps: Codable, Equatable {
    var frequency: Double
    var gainDb: Double

    init(frequency: Double, gainDb: Double = 0) {
        self.frequency = frequency
        self.gainDb = gainDb
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        frequency = c.lenient(.frequency, 1000)
        gainDb = c.lenient(.gainDb, 0)
    }

    static let lowShelf = EqShelfProps(frequency: 100)
    static let highShelf = EqShelfProps(frequency: 8000)

    var dictionary: [String: Any] { ["frequency": frequency, "gain_db": gainDb] }
}

/// An RBJ peaking bell: its centre in Hz, its gain in dB and its Q.
struct EqBandProps: Codable, Equatable {
    var frequency: Double
    var gainDb: Double
    var q: Double

    init(frequency: Double = 1000, gainDb: Double = 0, q: Double = 1) {
        self.frequency = frequency
        self.gainDb = gainDb
        self.q = q
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        frequency = c.lenient(.frequency, 1000)
        gainDb = c.lenient(.gainDb, 0)
        q = c.lenient(.q, 1)
    }

    var dictionary: [String: Any] { ["frequency": frequency, "gain_db": gainDb, "q": q] }
}

/// The clip's EQ (AU-31): seven named slots in signal order, nil when off,
/// and `bypass`, which keeps the settings and silences them.
struct EqProps: Codable, Equatable {
    var highPass: EqPassProps?
    var lowShelf: EqShelfProps?
    var band1: EqBandProps?
    var band2: EqBandProps?
    var band3: EqBandProps?
    var highShelf: EqShelfProps?
    var lowPass: EqPassProps?
    var bypass: Bool

    init(
        highPass: EqPassProps? = nil, lowShelf: EqShelfProps? = nil, band1: EqBandProps? = nil,
        band2: EqBandProps? = nil, band3: EqBandProps? = nil, highShelf: EqShelfProps? = nil,
        lowPass: EqPassProps? = nil, bypass: Bool = false
    ) {
        self.highPass = highPass
        self.lowShelf = lowShelf
        self.band1 = band1
        self.band2 = band2
        self.band3 = band3
        self.highShelf = highShelf
        self.lowPass = lowPass
        self.bypass = bypass
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        highPass = c.lenient(.highPass)
        lowShelf = c.lenient(.lowShelf)
        band1 = c.lenient(.band1)
        band2 = c.lenient(.band2)
        band3 = c.lenient(.band3)
        highShelf = c.lenient(.highShelf)
        lowPass = c.lenient(.lowPass)
        bypass = c.lenient(.bypass, false)
    }

    /// How many slots are on.
    var activeCount: Int {
        [highPass != nil, lowShelf != nil, band1 != nil, band2 != nil, band3 != nil,
         highShelf != nil, lowPass != nil].filter { $0 }.count
    }

    /// The patch's body. EVERY slot key is written, `NSNull` for an off slot,
    /// because a patch merges per key (`patch.rs`): a slot left out would
    /// keep its stored value rather than turn off.
    var dictionary: [String: Any] {
        func slot(_ value: [String: Any]?) -> Any { value ?? NSNull() }
        return [
            "high_pass": slot(highPass?.dictionary), "low_shelf": slot(lowShelf?.dictionary),
            "band_1": slot(band1?.dictionary), "band_2": slot(band2?.dictionary),
            "band_3": slot(band3?.dictionary), "high_shelf": slot(highShelf?.dictionary),
            "low_pass": slot(lowPass?.dictionary), "bypass": bypass,
        ]
    }
}

/// The hum notch comb (AU-33): mains 50 or 60 Hz, each notch's depth in
/// dB, and how many harmonics it takes.
struct HumProps: Codable, Equatable {
    var frequency: Int
    var depthDb: Double
    var harmonics: Int

    init(frequency: Int = 60, depthDb: Double = 30, harmonics: Int = 4) {
        self.frequency = frequency
        self.depthDb = depthDb
        self.harmonics = harmonics
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        frequency = c.lenient(.frequency, 60)
        depthDb = c.lenient(.depthDb, 30)
        harmonics = c.lenient(.harmonics, 4)
    }

    var dictionary: [String: Any] {
        ["frequency": frequency, "depth_db": depthDb, "harmonics": harmonics]
    }
}

/// The EQ section's three voice presets (AU-32). Each writes only its own
/// slot and `bypass: false`, so they combine.
enum EqPreset: CaseIterable {
    case rumbleCut, deMud, presence

    var title: String {
        switch self {
        case .rumbleCut: return "Rumble Cut"
        case .deMud: return "De-mud"
        case .presence: return "Presence"
        }
    }

    func applied(to eq: EqProps) -> EqProps {
        var next = eq
        next.bypass = false
        switch self {
        case .rumbleCut: next.highPass = EqPassProps(frequency: 80, slope: 24)
        case .deMud: next.band1 = EqBandProps(frequency: 300, gainDb: -3, q: 1)
        case .presence: next.band3 = EqBandProps(frequency: 4000, gainDb: 3, q: 1)
        }
        return next
    }
}
import AppKit

/// The Limiter section (spec §11 AU-26): the clip's true-peak limiter, last
/// in its chain, so the section comes after Mix — the Sound sub-tab's
/// sections read in the signal's order. `set_audio`'s `limiter` is its MCP
/// mirror.
extension AudioPane {

    /// "Limit peaks", Ceiling (dBTP, −24…0) and Release (ms, 1…1000).
    ///
    /// Every control writes a whole `LimiterProps`, the compressor's way: the
    /// patch replaces the object, so each edit re-sends the other value as it
    /// stands. With an action selected it writes the action's end, "Limit
    /// peaks" turned off there keying it off (spec §11 AU-88).
    ///
    /// The ceiling holds AFTER the clip's fader at its base volume (AU-22):
    /// fades and ducks only lower it, so it is what the clip sends the mix at
    /// most. The release is in milliseconds and not snapped to the frame
    /// grid, for the compressor's reason.
    func limiterSection() -> InspectorSection {
        let binding = self.binding
        func current() -> LimiterProps { binding.audioProps.limiter ?? LimiterProps() }
        func ops(_ next: LimiterProps) -> [ReelOp] {
            binding.ops(audio: AudioPatch(limiter: .some(next)))
        }
        func on() -> Bool { binding.audioProps.limiter != nil }
        func ticks(_ milliseconds: Double) -> Ticks {
            Ticks((max(milliseconds, 0) / 1000 * Double(ReelTime.perSecond)).rounded())
        }
        func milliseconds(_ ticks: Ticks) -> Double {
            Double(ticks) / Double(ReelTime.perSecond) * 1000
        }
        return InspectorSection(
            id: "audio.limiter", title: "Limiter",
            summary: {
                guard on() else { return "off" }
                return String(format: "%.1f dBTP", current().ceilingDb)
                    .replacingOccurrences(of: "-", with: "−")
            },
            reset: { binding.apply("Limiter", audio: AudioPatch(limiter: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Limit peaks", binding, name: "Limiter",
                    read: on,
                    ops: { value in
                        binding.ops(
                            audio: AudioPatch(limiter: value ? .some(LimiterProps()) : .some(nil)))
                    },
                    mixed: { binding.mixedAudio { $0.limiter != nil } }),
                inspectorValueRow(
                    "Ceiling", binding, name: "Limiter Ceiling", unit: " dBTP", decimals: 1,
                    min: -24, max: 0, quick: [-1, -2, -3, -6],
                    read: { current().ceilingDb },
                    ops: { value in
                        var l = current()
                        l.ceilingDb = value
                        return ops(l)
                    },
                    mixed: { binding.mixedAudio { $0.limiter?.ceilingDb } },
                    enabled: on),
                inspectorValueRow(
                    "Release", binding, name: "Limiter Release", unit: " ms", decimals: 0,
                    min: 1, max: 1000, quick: [50, 100, 200, 500],
                    read: { milliseconds(current().release) },
                    ops: { value in
                        var l = current()
                        l.release = ticks(value)
                        return ops(l)
                    },
                    mixed: { binding.mixedAudio { $0.limiter?.release } },
                    enabled: on),
            ])
    }
}

import AppKit

/// The Gate, Leveller and De-esser sections (spec §11 AU-48, AU-66): after
/// Noise Reduction and before Compressor, the signal's order (AU-47, AU-66).
/// `set_audio`'s `gate`, `leveller` and `de_esser` are their MCP mirror.
///
/// Every control writes a whole `GateProps`, `LevellerProps` or
/// `DeEsserProps`, the limiter's way; with an action selected both write the action's end (spec
/// §11 AU-88), a stage turned off there keyed off. Both thresholds are dB
/// relative to the clip's measured loudness (AU-41): the Status read-out says
/// where that puts the threshold in dBFS, or why the stage is not acting
/// (AU-42), and the Loudness read-out the level it is relative to — both
/// through the pane's `loudnessMemo`, the Volume section's own reading. The
/// times are in milliseconds and not snapped to the frame grid, for the
/// compressor's reason. The leveller's target is relative to the same level,
/// its Status read off its curves (AU-66 (e)).
extension AudioPane {

    /// "Gate pauses", Threshold, Ratio, Range, Attack, Hold, Release, Status,
    /// Loudness.
    func gateSection() -> InspectorSection {
        let binding = self.binding
        func current() -> GateProps { binding.audioProps.gate ?? GateProps() }
        func ops(_ next: GateProps) -> [ReelOp] {
            binding.ops(audio: AudioPatch(gate: .some(next)))
        }
        func on() -> Bool { binding.audioProps.gate != nil }
        func row(
            _ title: String, _ name: String, unit: String, decimals: Int, min: Double,
            max: Double, quick: [Double], width: CGFloat = InspectorMetrics.fieldWidth,
            read: @escaping (GateProps) -> Double,
            write: @escaping (inout GateProps, Double) -> Void
        ) -> NSView {
            inspectorValueRow(
                title, binding, name: name, unit: unit, decimals: decimals, min: min, max: max,
                quick: quick, width: width, read: { read(current()) },
                ops: { value in
                    var g = current()
                    write(&g, value)
                    return ops(g)
                },
                mixed: { binding.mixedAudio { $0.gate.map(read) } }, enabled: on)
        }
        return InspectorSection(
            id: "audio.gate", title: "Gate",
            summary: { on() ? AudioPane.decibels(current().thresholdDb, "%.0f dB") : "off" },
            reset: { binding.apply("Gate", audio: AudioPatch(gate: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Gate pauses", binding, name: "Gate",
                    read: on,
                    ops: { value in
                        binding.ops(audio: AudioPatch(gate: value ? .some(GateProps()) : .some(nil)))
                    },
                    mixed: { binding.mixedAudio { $0.gate != nil } }),
                row(
                    "Threshold", "Gate Threshold", unit: " dB", decimals: 0, min: -40, max: 0,
                    quick: [-20, -15, -10, -6], read: { $0.thresholdDb },
                    write: { $0.thresholdDb = $1 }),
                row(
                    "Ratio", "Gate Ratio", unit: ":1", decimals: 1, min: 1, max: 20,
                    quick: [2, 4, 10, 20], read: { $0.ratio }, write: { $0.ratio = $1 }),
                row(
                    "Range", "Gate Range", unit: " dB", decimals: 0, min: 1, max: 80,
                    quick: [10, 20, 40, 80], read: { $0.rangeDb }, write: { $0.rangeDb = $1 }),
                row(
                    "Attack", "Gate Attack", unit: " ms", decimals: 0, min: 0, max: 100,
                    quick: [1, 5, 10], read: { AudioPane.milliseconds($0.attack) },
                    write: { $0.attack = AudioPane.ticks($1) }),
                row(
                    "Hold", "Gate Hold", unit: " ms", decimals: 0, min: 0, max: 500,
                    quick: [0, 50, 100, 200], read: { AudioPane.milliseconds($0.hold) },
                    write: { $0.hold = AudioPane.ticks($1) }),
                row(
                    "Release", "Gate Release", unit: " ms", decimals: 0, min: 1, max: 2000,
                    quick: [50, 100, 250, 500], width: InspectorMetrics.wideFieldWidth,
                    read: { AudioPane.milliseconds($0.release) },
                    write: { $0.release = AudioPane.ticks($1) }),
                inspectorRow(
                    "Status",
                    [
                        inspectorReadout(width: 170) { [weak self] in
                            guard on() else { return "off" }
                            return self?.dynamicsStatus(
                                relative: current().thresholdDb, acting: "Opens above",
                                idle: "Not gating") ?? "—"
                        }
                    ]),
                inspectorRow(
                    "Loudness",
                    [
                        inspectorReadout(width: 170) { [weak self] in
                            self?.dynamicsLoudness() ?? "—"
                        }
                    ]),
            ])
    }

    /// "Ride the level", Target, Max Boost, Max Cut, Response, Status,
    /// Loudness (AU-66 (g)). The Status reads the clip's curves, made ahead of
    /// time from its loudness and speech; Response takes effect at an
    /// action's end (held, AU-66 (f)).
    func levellerSection() -> InspectorSection {
        let binding = self.binding
        func current() -> LevellerProps { binding.audioProps.leveller ?? LevellerProps() }
        func ops(_ next: LevellerProps) -> [ReelOp] {
            binding.ops(audio: AudioPatch(leveller: .some(next)))
        }
        func on() -> Bool { binding.audioProps.leveller != nil }
        func row(
            _ title: String, _ name: String, unit: String, decimals: Int, min: Double,
            max: Double, quick: [Double], width: CGFloat = InspectorMetrics.fieldWidth,
            read: @escaping (LevellerProps) -> Double,
            write: @escaping (inout LevellerProps, Double) -> Void
        ) -> NSView {
            inspectorValueRow(
                title, binding, name: name, unit: unit, decimals: decimals, min: min, max: max,
                quick: quick, width: width, read: { read(current()) },
                ops: { value in
                    var l = current()
                    write(&l, value)
                    return ops(l)
                },
                mixed: { binding.mixedAudio { $0.leveller.map(read) } }, enabled: on)
        }
        return InspectorSection(
            id: "audio.leveller", title: "Leveller",
            summary: { on() ? AudioPane.decibels(current().targetDb, "%.0f dB") : "off" },
            reset: { binding.apply("Leveller", audio: AudioPatch(leveller: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Ride the level", binding, name: "Leveller",
                    read: on,
                    ops: { value in
                        binding.ops(
                            audio: AudioPatch(leveller: value ? .some(LevellerProps()) : .some(nil)))
                    },
                    mixed: { binding.mixedAudio { $0.leveller != nil } }),
                row(
